/*====================================================================
FUNCTION: tdsrrcllc_copy_mac_cipher_config()

DESCRIPTION:
  This function copies the MAC cipher config present in 'tdscipher_config_db' to
  passed argument.

DEPENDENCIES:
  None.

RETURN VALUE:
  None.

SIDE EFFECTS:
  None.

=====================================================================*/
static void tdsrrcllc_copy_mac_cipher_config
(
  tdsmac_cipher_config_type cipher_info[TDSMAX_CN_DOMAIN]
)
{
  uint8 i=0;

  /* Update ciphering information using the global ciphering database maitained by SMC */
  for(i=0; i<RRC_MAX_CN_DOMAINS; i++)
  {
    cipher_info[i] = tdscipher_config_db.mac_cipher_info[i];
  }
}
/*====================================================================
FUNCTION: tdsrrcllc_clear_config_all_db()

DESCRIPTION:
  This function is called to clear are the DB while going to disconnected

DEPENDENCIES:
  None.

RETURN VALUE:
  None.

SIDE EFFECTS:
  None.

=====================================================================*/
static void tdsrrcllc_clear_config_all_db
(
  void
)
{
  
  if(tdscurrent_config_ptr == NULL)
  {
    TDSRRC_MSG0(MSG_LEGACY_HIGH,"CC/OC/TOC already freed.");
    return;
  }

  /* Initialize Ordered and Current Configs */
  tdsrrcllc_init_ordered_config_status_and_data(TDSRRC_STATE_DISCONNECTED);
  tdsrrcllc_init_config_data(tdscurrent_config_ptr, TDSRRC_STATE_DISCONNECTED);
  
  /* Initialize Transition Config */
  tdsrrcllc_init_config_data(tdstransition_config.toc_ptr, TDSRRC_STATE_DISCONNECTED);
  tdstransition_config.toc_usage = TDSTOC_INVALID;
  
   tdstoc_usage_change_oos_to_dch = FALSE; 
  /* Clear RLC Logical Channel Info in LCM */
  tdsrrclcm_clear_rlc_lc_info(
    );
  /* Initialize LLC and initialize Command under process */
  tdsrrcllc_init(TDSRRCLLC_RE_INIT_FREE_Q
              );
  
  
  
}
