/*====================================================================
FUNCTION: tdsrrcllc_send_rrc_cell_reselection_cnf()

DESCRIPTION:
  This function constructs the TDSRRC_CELL_RESELECTION_CNF primitive and
  sends it to the passed RRC procedure.

DEPENDENCIES:
  None

RETURN VALUE:
  uecomdef_status_e_type -> indicating a SUCCESS or FAILURE

SIDE EFFECTS:
  None.
====================================================================*/
static uecomdef_status_e_type
tdsrrcllc_send_rrc_cell_reselection_cnf
(
  uecomdef_status_e_type status
)
{
  tdsrrc_cmd_type  *rrc_cmd_ptr;
  if( (rrc_cmd_ptr = tdsrrc_get_int_cmd_buf()) == NULL)
  {
    ERR_FATAL("NULL Ptr when Sending TDSRRC_CELL_RESELECTION_CNF",0,0,0);
  }

  TDSRRC_MSG0(MSG_LEGACY_LOW,"Sending TDSRRC_CELL_RESELECTION_CNF");

  /* Fill in the local command header.*/
  rrc_cmd_ptr->cmd_hdr.cmd_id = TDSRRC_CELL_RESELECTION_CNF;
  rrc_cmd_ptr->cmd.cell_resel_cnf.status = status;
  if((status == FAILURE ) && 
    (tdsrrcllc_cmd_under_process.chan_config.current_cmd_engine == TDSLLC_CELL_RESELECTION_ENGINE)
    && (tdsrrc_get_state() == TDSRRC_STATE_CELL_FACH ))
  {
    /*Restore the URNTI to the OC as it is still valid*/
    if (tdsrrcllc_backup_rnti_info.rnti_valid != TDSNO_RNTI_VALID)   
    {
      TDSRRC_MSG3(MSG_LEGACY_HIGH,"Restore  CC & OC RNTI status %d CRNTI %d URNTI %d ", 
               tdsrrcllc_backup_rnti_info.rnti_valid,tdsrrcllc_backup_rnti_info.crnti,tdsrrcllc_backup_rnti_info.urnti);
      /* copy the rnti information to both oc and cc */
      tdsordered_config_ptr->mac_dl_parms.rnti_info =
             tdscurrent_config_ptr->mac_dl_parms.rnti_info=  tdsrrcllc_backup_rnti_info;
      tdsordered_config_ptr->mac_ul_parms.rnti_info =
            tdscurrent_config_ptr->mac_ul_parms.rnti_info = tdsrrcllc_backup_rnti_info;
    }   
  }

  memset(&tdsrrcllc_backup_rnti_info,0,sizeof(tdsmac_rnti_config_type));
  /* Send the internal command */
  tdsrrc_put_int_cmd(rrc_cmd_ptr);

  return(SUCCESS);
} /* tdsrrcllc_send_rrc_cell_reselection_cnf */


