/*===========================================================================
FUNCTION    tdsrrcllc_init_cmd_under_process_data

DESCRIPTION
  This function initializes the RRC LLC command under process data.

DEPENDENCIES
  None.

RETURN VALUE
  None.

SIDE EFFECTS
  None.
===========================================================================*/
static void tdsrrcllc_init_cmd_under_process_data(void)
{
  uint8 l1_req_index;
  /* Invalidate the data first */
  tdsrrcllc_cmd_under_process.valid = FALSE;
  tdsrrcllc_cmd_under_process.procedure = TDSRRC_PROCEDURE_NONE;
  tdsrrcllc_cmd_under_process.rrc_current_cmd_id = TDSRRC_INT_CMD_BASE;
  tdsrrcllc_cmd_under_process.clear_oc_pending = FALSE;
  tdsrrcllc_cmd_under_process.update_mac_with_rnti = FALSE;
  tdsrrcllc_cmd_under_process.sccpch_selec_reqd = FALSE;
  tdsrrcllc_cmd_under_process.chan_config.solo_bch_operation = FALSE;
  tdsrrcllc_cmd_under_process.chan_config.chan_est_ind_rcvd = FALSE;
  tdsrrcllc_cmd_under_process.chan_config.current_cmd_engine = TDSLLC_NO_ENGINE;
  tdsrrcllc_cmd_under_process.chan_config.chan_config_reason = TDSRRCLLC_CHAN_CFG_REASON_NONE;
  tdsrrcllc_cmd_under_process.chan_config.new_freq = FALSE;
  tdsrrcllc_cmd_under_process.is_hho_in_dch = FALSE;

  tdsrrcllc_cmd_under_process.chan_config.hsdpa_inactive_to_active = FALSE;
  tdsrrcllc_cmd_under_process.chan_config.hsdpa_active_to_inactive = FALSE;
#ifdef FEATURE_TDSCDMA_HSDPA_MAC_EHS
  tdsrrcllc_cmd_under_process.chan_config.hsdpa_ehs_to_hs = FALSE;
  tdsrrcllc_cmd_under_process.chan_config.hsdpa_hs_to_ehs = FALSE;
#endif
  /* Set number of CCTrCH IDs to release to 0 */
  tdsrrcllc_cmd_under_process.chan_config.cctrch_id_release_list.num_ids = 0;

  /* Set number of stored L1 requests to 0 */
  tdsrrcllc_cmd_under_process.chan_config.l1_req_list.num_l1_req = 0;
  tdsrrcllc_cmd_under_process.chan_config.l1_req_list.current_l1_req = -1;
  /* Initialize all L1 command buffers so they don't have any residual data values */
  for(l1_req_index=0; l1_req_index<TDSLLC_MAX_L1_CMDS_PER_RRC_INTERN_CMD; l1_req_index++)
  {
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.hsdpa_l1_ops = TDSL1_HSDPA_SETUP_OPS_NOOP;
        tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.hsdpa_l1_info = NULL;
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.add_dl_phychan = TDSL1_DL_PHYCHAN_NOCHAN;
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.add_dl_phychan_db = NULL;
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.cfg_dl_phychan = TDSL1_DL_PHYCHAN_NOCHAN;
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.cfg_dl_phychan_db = NULL;
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.drop_dl_phychan = TDSL1_DL_PHYCHAN_NOCHAN;
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.dl_cctrch_info = NULL;
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.dl_ctfc_info = NULL;

    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.add_ul_phychan = TDSL1_UL_NUM_PHYCHAN;
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.add_ul_phychan_db = NULL;
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.cfg_ul_phychan = TDSL1_UL_NUM_PHYCHAN;
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.cfg_ul_phychan_db = NULL;
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.drop_ul_phychan = TDSL1_UL_NUM_PHYCHAN;
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.ul_cctrch_info = NULL;

    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.req_mask = 0;
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.ho_setup_mask = 0;
#ifdef FEATURE_TDSCDMA_MTPL_THERMAL_BACKOFF 
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.is_emergency_call = FALSE;
#endif
#ifdef FEATURE_TDSCDMA_REL9
#ifdef FEATURE_TDSCDMA_DMO_SUPPORT
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.meas_occasion_info_incl = FALSE;
    tdsrrcllc_cmd_under_process.chan_config.l1_req_list.l1_req[l1_req_index].cmd.setup.meas_occasion_info = NULL;
#endif
#endif
  }   /* for(...) */

  /* Initialize RLC config request list with number of logical channels
   * for each logical channel type set to 0
   */
  tdsrrcllc_cmd_under_process.chan_config.rlc_config_req_list.dl_tm.nchan = 0;
  tdsrrcllc_cmd_under_process.chan_config.rlc_config_req_list.ul_tm.nchan = 0;
  tdsrrcllc_cmd_under_process.chan_config.rlc_config_req_list.dl_um.nchan = 0;


  for(l1_req_index=0; l1_req_index < TDSUE_MAX_DL_UM_CHANNEL; l1_req_index++)
  {
    tdsrrcllc_cmd_under_process.chan_config.rlc_config_req_list.dl_um.chan_info[l1_req_index].alternate_e_bit = FALSE;
  }
  for(l1_req_index=0; l1_req_index < TDSUE_MAX_UL_UM_CHANNEL; l1_req_index++)
  {
    tdsrrcllc_cmd_under_process.chan_config.rlc_config_req_list.ul_um.chan_info[l1_req_index].alternate_e_bit = FALSE;
  }  
  
  tdsrrcllc_cmd_under_process.chan_config.rlc_config_req_list.ul_um.nchan = 0;

  tdsrrcllc_cmd_under_process.chan_config.rlc_config_req_list.am.nentity = 0;

#ifdef FEATURE_UMTS_PDCP
  tdsrrcllc_cmd_under_process.chan_config.pdcp_config_req_list.num_rbs = 0;
#endif /* FEATURE_UMTS_PDCP */

  /* Initialize each of the physical channel action data */
  tdsrrcllc_cmd_under_process.chan_config.phy_chan_action_list.pccpch_action
    = TDSLLC_PHYCHAN_NO_OP;
  tdsrrcllc_cmd_under_process.chan_config.phy_chan_action_list.n_pccpch_action
    = TDSLLC_PHYCHAN_NO_OP;
  tdsrrcllc_cmd_under_process.chan_config.phy_chan_action_list.sccpch_action
    = TDSLLC_PHYCHAN_NO_OP;
  tdsrrcllc_cmd_under_process.chan_config.phy_chan_action_list.ul_dpch_action
    = TDSLLC_PHYCHAN_NO_OP;
  tdsrrcllc_cmd_under_process.chan_config.phy_chan_action_list.dl_dpch_action
    = TDSLLC_PHYCHAN_NO_OP;
  tdsrrcllc_cmd_under_process.chan_config.phy_chan_action_list.prach_action
    = TDSLLC_PHYCHAN_NO_OP;
  tdsrrcllc_cmd_under_process.chan_config.phy_chan_action_list.aset_update
    = FALSE;

  /* Initialize the loopback test mode to "None" */
  tdsrrcllc_cmd_under_process.chan_config.lb_test_mode = TDSLB_TEST_MODE_NONE;
  tdsrrcllc_cmd_under_process.chan_config.dummy_signaling_enabled = FALSE;

  /* Initialise status of Channel Config Request */
  tdsrrcllc_cmd_under_process.chan_config.chan_cfg_status = TDSRRCLLC_CHAN_CFG_SUCCESS;

  tdsrrcllc_cmd_under_process.err_recovery_in_progress = FALSE;
  /* initialize the tdsrlc_rel_list that is used for failure handling */

  tdsrlc_rel_list.dl_tm.nchan = 0;
  tdsrlc_rel_list.ul_tm.nchan = 0;
  tdsrlc_rel_list.dl_um.nchan = 0;
  tdsrlc_rel_list.ul_um.nchan = 0;
  tdsrlc_rel_list.am.nentity = 0;

  memset(&tdsrrcllc_backup_rnti_info,0,sizeof(tdsmac_rnti_config_type));
  /* add a flag, remind revert process for CR354247. */
  tdsrrcllc_cmd_under_process.is_revert_process = FALSE;

} /* tdsrrcllc_init_cmd_under_process_data */


/*====================================================================
FUNCTION: tdsrrcllc_init()

DESCRIPTION:
  This function initializes all RRCLLC data including CCTrCH ID database,
  Command under process data, LLC internal queue and
  the TDSORDERED_CONFIG databases. This calls a number of other
  initialization functions.

DEPENDENCIES:
  None.

RETURN VALUE:
  None.

SIDE EFFECTS:
  None.
====================================================================*/
void tdsrrcllc_init(tdsrrcllc_init_e_type  init_type
                 )
{
  /* command pointer for LLC */
  tdsrrc_cmd_type     *cmd_ptr;
  tdsrrc_cmd_type     *llc_stored_cmd_ptr;

  TDSRRC_MSG1(MSG_LEGACY_HIGH,"initialize rrcllc init_type:%d",init_type);

  /* Check if this initialization is at the startup time */
  if(init_type == TDSRRCLLC_STARTUP_INIT)
  {
    /* Initialize the RRC LLC command queue */
    tdsrrcllc_queue_init();
  }
  else if(init_type == TDSRRCLLC_RE_INIT_FREE_Q)
  {
    /* Dequeue internal LLC queue and free all buffers */
    while( q_check(&tdsrrcllc_cmd_q) != NULL )
    {
      if( (llc_stored_cmd_ptr = (tdsrrc_cmd_type *) q_get(&tdsrrcllc_cmd_q)) != NULL )
      {
        /* If Measurement request or TVM is found also free the
               * embedded pointer inside the command
               */
        tdsrrcllc_free_cmd_and_embedded_buf(llc_stored_cmd_ptr);
      }
    }
  }
  /* Initialize the CCTrCH ID's */
  tdsrrcllc_init_cctrch_id(
    );

  /* Initialize Command under process data */
  tdsrrcllc_init_cmd_under_process_data();

  if(init_type == TDSRRCLLC_STARTUP_INIT)
  {
    tdstransition_config.toc_ptr = NULL;
    tdscurrent_config_ptr = NULL;
    tdsordered_config_ptr = NULL;

    if (tdsrrc_nv_rel_indicator & TDSRRC_NV_REL_INDICATOR_REL5) 
    {
      TDSRRC_MSG0(MSG_LEGACY_HIGH,"RRCHS:Startup. Set action NOOP");
    }
    tdsrrc_set_hsdpa_action(TDSHSDPA_NOOP);
    if (tdsrrc_nv_rel_indicator & TDSRRC_NV_REL_INDICATOR_REL5) 
    {
      TDSRRC_MSG0(MSG_LEGACY_HIGH,"RRCHS:Startup. Set status INACTIVE");
    }
    tdsrrc_set_hsdpa_status(TDSHSDPA_INACTIVE);

    /* Initialize no of RLC size per RB Struct */

    tdsrrc_initialize_rlc_size_per_rb();
    tdsrrc_initialize_rlc_size_change();

    /* Send Layer 1 to their Idle State */
    if((cmd_ptr = tdsrrc_get_int_cmd_buf()) == NULL)
    {
      ERR_FATAL("NULL Ptr when sending TDSRRC_RESET_L1_CNF",0,0,0);
    }
    /* Reset L1 */
    cmd_ptr->cmd_hdr.cmd_id = TDSRRC_RESET_L1_REQ;
    cmd_ptr->cmd.rrc_reset_l1_req.reset_l1_cnf_needed = FALSE;
    tdsrrc_put_int_cmd(cmd_ptr);

    tdstransition_config.toc_usage = TDSTOC_INVALID;
    tdstoc_usage_change_oos_to_dch = FALSE;

  }
  /* Initialize current physical channel data for all DL physical channels */
  tdsrrcllc_init_semi_permanent_data();

  return;
} /* tdsrrcllc_init */

