/*====================================================================
FUNCTION: tdsrrcllc_send_rrc_channel_config_cnf()

DESCRIPTION:
  This function constructs the TDSRRC_CHANNEL_CONFIG_CNF primitive and
  sends it to the passed RRC procedure.

DEPENDENCIES:
  None

RETURN VALUE:
  uecomdef_status_e_type -> indicating a SUCCESS or FAILURE

SIDE EFFECTS:
  None.
====================================================================*/
uecomdef_status_e_type
tdsrrcllc_send_rrc_channel_config_cnf
(
 tdsrrc_proc_e_type               proc_type,
 uint32                        tdstransaction_id,
 tdsrrcllc_chan_cfg_status_e_type chan_cfg_status
)
{
  tdsrrc_cmd_type  *rrc_cmd_ptr;
  #ifdef FEATURE_TDSCDMA_ONE_SIDE_REEST 
  tdsl2_ul_cmd_type  *rlc_ptr = NULL;
  tdsl2_dl_cmd_type  *rlc_ptr_dl = NULL;

  uint8 i = 0;
  #endif
  #ifdef FEATURE_TDSCDMA_ONE_SIDE_REEST 
   if (tdsrrcrlc_continue_reest.rb_num > 0)
   {
      if ((rlc_ptr = tdsl2_ul_get_cmd_buf()) == NULL)
      {
        ERR_FATAL("RRC_ONE_SIDE:NULL Ptr when sending TDSCRLC_UL_RESUME_REQ ",0,0,0);
      }

      if ((rlc_ptr_dl = tdsl2_dl_get_cmd_buf()) == NULL)
      {
        ERR_FATAL("RRC_ONE_SIDE:NULL Ptr when sending CRLC_DL_RESUME_REQ ",0,0,0);
      }
      rlc_ptr->cmd_hdr.cmd_id = TDSCRLC_UL_CONTINUE_REQ;
      rlc_ptr_dl->cmd_hdr.cmd_id = TDSCRLC_DL_CONTINUE_REQ;
      rlc_ptr->cmd_data.ul_continue.nchan = tdsrrcrlc_continue_reest.rb_num;
      rlc_ptr_dl->cmd_data.dl_continue.nchan = tdsrrcrlc_continue_reest.rb_num;
      
      for(i = 0;i < tdsrrcrlc_continue_reest.rb_num; i++)
      {
        rlc_ptr_dl->cmd_data.dl_continue.channel[i] = tdsrrclcm_get_dl_rlc_lc_id(tdsrrcrlc_continue_reest.rb_id[i]);

        rlc_ptr->cmd_data.ul_continue.channel[i] = tdsrrclcm_get_ul_rlc_lc_id(tdsrrcrlc_continue_reest.rb_id[i]);
        TDSRRC_MSG1(MSG_LEGACY_HIGH,"RRC_ONE_SIDE: CONTINUE Both Side RB ID  %d ",tdsrrcrlc_continue_reest.rb_id[i]);
      } 
      tdsl2_ul_put_cmd(rlc_ptr);
      /* Send command to L2 UL Task */
      tdsl2_dl_put_cmd(rlc_ptr_dl);

      memset(&tdsrrcrlc_continue_reest, 0, sizeof(tdsrrcllc_continue_rlc_data_type) );

   }

#endif
  if( (rrc_cmd_ptr = tdsrrc_get_int_cmd_buf()) == NULL)
  {
    ERR_FATAL("NULL Ptr when Sending TDSRRC_CHANNEL_CONFIG_CNF",0,0,0);
  }

  TDSRRC_MSG2(MSG_LEGACY_HIGH,"Sending CHANNEL_CONFIG_CNF, proc %d,status %d",proc_type,chan_cfg_status);

  /* Fill in the local command header.*/
  rrc_cmd_ptr->cmd_hdr.cmd_id = TDSRRC_CHANNEL_CONFIG_CNF;
  rrc_cmd_ptr->cmd.chan_config_cnf.procedure =  proc_type;
  rrc_cmd_ptr->cmd.chan_config_cnf.transaction_id =  tdstransaction_id;
  rrc_cmd_ptr->cmd.chan_config_cnf.chan_cfg_status = chan_cfg_status;

  if(tdsrrcllc_cmd_under_process.chan_config.hho_ciph_update_required == TRUE)
  {
    rrc_cmd_ptr->cmd.chan_config_cnf.inter_freq_hho_status = TRUE;
    tdsrrcllc_cmd_under_process.chan_config.hho_ciph_update_required = FALSE;
  }
  else
  {
    rrc_cmd_ptr->cmd.chan_config_cnf.inter_freq_hho_status = FALSE;
  }

  if((chan_cfg_status != TDSRRCLLC_CHAN_CFG_SUCCESS) &&
     ((proc_type == TDSRRC_PROCEDURE_CU)
          || (proc_type == TDSRRC_PROCEDURE_PCR) 
          || (proc_type == TDSRRC_PROCEDURE_RBE)
          || (proc_type == TDSRRC_PROCEDURE_RBR)
          || (proc_type == TDSRRC_PROCEDURE_RBRC)
          || (proc_type == TDSRRC_PROCEDURE_TCR)) 
    )
  {
    TDSRRC_MSG1(MSG_LEGACY_HIGH,"inter_freq_hho_status:%d",rrc_cmd_ptr->cmd.chan_config_cnf.inter_freq_hho_status);
    tdsrrcsmc_reset_start_value_to_transmit_cs_hho(TRUE);
  }
#ifdef FEATURE_TDSCDMA_RRC_INDICATE_CODEC_TO_CM
  if(TDSRRC_STATE_CELL_DCH == tdsrrcllc_cmd_under_process.next_rrc_state &&
    ((proc_type == TDSRRC_PROCEDURE_PCR) 
      || (proc_type == TDSRRC_PROCEDURE_RBE)
      || (proc_type == TDSRRC_PROCEDURE_RBR)
      || (proc_type == TDSRRC_PROCEDURE_RBRC)
      || (proc_type == TDSRRC_PROCEDURE_TCR)))
  {
      if(TDSRRCLLC_CHAN_CFG_SUCCESS != chan_cfg_status)
      {
        /*Send HHO complete to CM*/
        tdsrrc_send_hho_cmd_to_cm(SYS_HO_FAIL);
      }
      else
      {
              /*Send HHO complete to CM*/
        tdsrrc_send_hho_cmd_to_cm(SYS_HO_COMPLETE);
      }
      tdsrrc_set_ordered_codec_status(FALSE);
  }
#endif

  /* Send the internal command */
  tdsrrc_put_int_cmd(rrc_cmd_ptr);

  if ((proc_type == TDSRRC_PROCEDURE_RCE) ||
      (proc_type == TDSRRC_PROCEDURE_RBE) ||
      (proc_type == TDSRRC_PROCEDURE_RBRC) ||
      (proc_type == TDSRRC_PROCEDURE_RBR) ||
      (proc_type == TDSRRC_PROCEDURE_TCR) ||
      (proc_type == TDSRRC_PROCEDURE_PCR) ||
      (proc_type == TDSRRC_PROCEDURE_CU) ||
      (proc_type == TDSRRC_PROCEDURE_RCR) ||
      (proc_type == TDSRRC_PROCEDURE_CHO) ||
      (proc_type == TDSRRC_PROCEDURE_IHO)
      ||((tdsrrcllc_cmd_under_process.procedure == TDSRRC_PROCEDURE_CSP)
            &&(tdsrrcllc_cmd_under_process.chan_config.chan_config_reason == TDSRRCLLC_CHAN_CFG_REASON_PHYCHAN_RESETUP)
            &&(tdsrrccsp_get_curr_scan() == TDSRRC_CSP_UNLOCK_BY_SCAN))
     )
  {
    /*Now we reset the HSDPA action for MAC and hs_reset_mask for L1 in Config DB*/
    tdsrrcllc_reset_mac_and_l1_for_hsdpa();  

#ifdef FEATURE_HSPA_CALL_STATUS_IND
    tdsrrc_send_hspa_call_status_info();
#endif /*FEATURE_HSPA_CALL_STATUS_IND*/

#ifdef FEATURE_TDSCDMA_HSUPA
    tdsrrcllc_reset_mac_and_l1_e_info_on_llc_cfg_cnf();

    if((chan_cfg_status == TDSRRCLLC_CHAN_CFG_FAILURE_BACK_TO_OLD_CONFIG)&&
       (tdscurrent_config_ptr->e_dch_transmission)&&
       (tdscurrent_config_ptr->l1_e_req_mask != TDSRRCLLC_EUL_NOOP))
    {
      /* clean up the EUL flags in CURRENT CONFIG PTR because 
      *we use CC to update bit masks for going back to old config 
      *seefunction tdsrrcllc_set_e_req_mask_for_old_config()
      */
      TDSRRC_MSG0(MSG_LEGACY_HIGH,"RRCEUL:Init EUL flgs from CC as CC->OC copy done");
      tdsrrcllc_init_e_dch_info_before_msg_processing(tdscurrent_config_ptr);
    }

    /*as part of Resume handler we would have set  current_config_ptr->l1_e_req_mask = START & after CHANC_CONFIG_CNF we don't do Swap OC and CC */
    if (((tdsrrcllc_cmd_under_process.procedure == TDSRRC_PROCEDURE_IHO || tdsrrcllc_cmd_under_process.procedure == TDSRRC_PROCEDURE_CHO)&&
                    (tdsrrc_get_state()== TDSRRC_STATE_CELL_DCH) &&
                    (tdsrrcllc_cmd_under_process.next_rrc_state == TDSRRC_STATE_CELL_DCH))
          ||((tdsrrcllc_cmd_under_process.procedure == TDSRRC_PROCEDURE_CSP)
                &&(tdsrrcllc_cmd_under_process.chan_config.chan_config_reason == TDSRRCLLC_CHAN_CFG_REASON_PHYCHAN_RESETUP)
                &&(tdsrrccsp_get_curr_scan() == TDSRRC_CSP_UNLOCK_BY_SCAN))
       )
    {
      if( (tdscurrent_config_ptr->e_dch_transmission)&&
           (tdscurrent_config_ptr->l1_e_req_mask != TDSRRCLLC_EUL_NOOP))
      {
        TDSRRC_MSG1(MSG_LEGACY_HIGH,"RRCEUL:Reset l1_e_req_mask <Prev value=%d> in CC",tdscurrent_config_ptr->l1_e_req_mask);
        tdscurrent_config_ptr->l1_e_req_mask = TDSRRCLLC_EUL_NOOP;
      }
    }

    /* Log HSUPA support status. Check HSUPA status from DCH to DCH.
       Otherwise log as unsupport */
    if ((tdsrrc_get_state() == TDSRRC_STATE_CELL_DCH) &&
        (tdsrrcllc_cmd_under_process.next_rrc_state == TDSRRC_STATE_CELL_DCH))
    {
       if (tdsrrc_get_hsupa_status() == TDSHSUPA_ACTIVE) 
       {
          tdsrrc_event_log_hsupa_support_status(SYS_HS_IND_HSUPA_SUPP_CELL);
       }
       else
       {
          tdsrrc_event_log_hsupa_support_status(SYS_HS_IND_HSDPA_HSUPA_UNSUPP_CELL);
       }
    }
#endif /* FEATURE_TDSCDMA_HSUPA */



#ifdef FEATURE_TDSCDMA_CPC_DTX
    tdsrrcllc_reset_l1_cpc_dtx_info_on_llc_cfg_cnf();
#endif

  }

  if(chan_cfg_status == TDSRRCLLC_CHAN_CFG_FAILURE_PHY_CHL)
  {
    TDS_SELF_HOSTING_EVENT_LOG(TDS_SELF_HOSTING_OWNER_RRC,
  	                           TDS_SELF_HOSTING_MAJOR_CALL_RETENTION_EXCEPTION,
  	                           TDS_SELF_HOSTING_MINOR_CPHY_SETUP_FAIL);
  }

  return(SUCCESS);
} /* tdsrrcllc_send_rrc_channel_config_cnf */



