#ifdef FEATURE_UMTS_PDCP
/*====================================================================
FUNCTION: tdsrrcllc_cpdcp_config_req()

DESCRIPTION:
  This function constructs the COMP_CPDCP_CONFIG_REQ primitive and
  sends it to PDCP layer.

DEPENDENCIES:
  None

RETURN VALUE:
  uecomdef_status_e_type -> indicating a SUCCESS or FAILURE

SIDE EFFECTS:
  None.
====================================================================*/
static uecomdef_status_e_type tdsrrcllc_cpdcp_config_req
(
 void
)
{

  comp_cmd_type  *pdcp_ptr;
  uint32 i= 0;

  /* Will send one pdcp command at a time.  So */
  for( i = 0; i < tdsrrcllc_cmd_under_process.chan_config.pdcp_config_req_list.num_rbs; i++)
  {
    /* Get PDCP command buffer */
    if ((pdcp_ptr = comp_get_cmd_buf()) == NULL)
    {
      ERR_FATAL("NULL Ptr when sending CPDCP_CONFIG_REQ ",0,0,0);
    }
    /* Fill in the Command Header */
    pdcp_ptr->hdr.cmd_id = CPDCP_CONFIG_REQ;
    pdcp_ptr->hdr.subs_id = tdsrrc_get_as_id();
    
    /* Fill in the Command Data */
    pdcp_ptr->cmd.pdcp_cfg_req = tdsrrcllc_cmd_under_process.chan_config.pdcp_config_req_list.pdcp_cfg_req[i];
    
    TDSRRC_MSG1(MSG_LEGACY_HIGH,"Sending COMP_CPDCP_CONFIG_REQ action %d",tdsrrcllc_cmd_under_process.chan_config.pdcp_config_req_list.pdcp_cfg_req[i].action);
    
    
    /* Send command to L2 UL Task */
    if(TDSCHECK_OPTIONAL_FEATURE_CFA_SUPPORTED)
    {
      tdscfa_comp_put_cmd(pdcp_ptr);
    }
    comp_put_cmd(pdcp_ptr);
  }
  return SUCCESS;
} /* tdsrrcllc_cpdcp_config_req() */
#endif /* FEATURE_UMTS_PDCP*/

