/*====================================================================
FUNCTION: tdsrrcllc_wait_cphy_cell_trans_cnf_handler()

DESCRIPTION:
  This function is a handler for TDSLLC_WAIT_CPHY_CELL_TRANSITION_CNF
  state and takes care of all incoming commands and Confirms from RRC
  procedures, MAC, RLC and L1.

DEPENDENCIES:
  None

RETURN VALUE:
  Next LLC state.

SIDE EFFECTS:
  None.
====================================================================*/
static tdsrrcllc_substate_e_type
tdsrrcllc_wait_cphy_cell_trans_cnf_handler(tdsrrc_cmd_type *cmd_ptr)
{

  tdsrrcllc_substate_e_type  rrcllc_next_substate = TDSLLC_WAIT_CPHY_CELL_TRANSITION_CNF;

  TDSRRC_MSG1(MSG_LEGACY_MED,"Cmd 0x%x recvd in TDSLLC_WAIT_CPHY_CELL_TRANSITION_CNF",cmd_ptr->cmd_hdr.cmd_id);

  switch(cmd_ptr->cmd_hdr.cmd_id)
  {
    case TDSRRC_CPHY_CELL_TRANSITION_CNF:

      /* Stop timer for L1 deadlock detection */
      tdsrrctmr_stop_timer( TDSRRCTMR_L1_DEADLOCK_DETECT_TIMER );

      /* Stop Delay Err Fatal timer if started*/
      if (tdsrrctmr_get_remaining_time(TDSRRCTMR_DELAY_ERR_FATAL_TIMER) > 0) 
      {
        tdsrrctmr_stop_timer(TDSRRCTMR_DELAY_ERR_FATAL_TIMER);
        TDSRRC_MSG0(MSG_LEGACY_ERROR,"Stopped Delay Err Fatal timer in TRANS_CNF");
      }

#ifdef FEATURE_QSH_EVENT_METRIC
      if(cmd_ptr->cmd.cell_transition_cnf.status == TRUE)
      {
        TDSRRC_QSH_SERVING_CELL_UPDATE();
      }
#endif

      if((tdsrrcllc_cmd_under_process.valid) &&
           (tdsrrcllc_cmd_under_process.rrc_current_cmd_id == TDSRRC_CELL_RESELECTION_REQ))
      {
        if(cmd_ptr->cmd.cell_transition_cnf.status == TRUE)
        {
          if(tdsrrcllc_command_engine(tdsrrcllc_current_substate, &rrcllc_next_substate)
               == FAILURE)
          {
              ERR_FATAL("RRC Config request processing failure",0,0,0);
          }
          else if(rrcllc_next_substate == TDSLLC_WAIT_NEW_CELL_IND)
          {
            /* This implies no more lower layer commands are to be sent. Send a RRC
             * RESLECTION CNF back to the procedure */
            if((tdsrrcllc_cmd_under_process.valid) &&
               (tdsrrcllc_cmd_under_process.rrc_current_cmd_id == TDSRRC_CELL_RESELECTION_REQ))
            {
              /* A swapping ensures the data space used to configure lower layers
               * for reselection will not be used for configuration in the next
               * reconfiguration. If CC was used for reselection, a L2 Ack will
               * make CC point to that data space again, ensuring the above condition.
               */
              tdsrrcllc_swap_oc_and_cc();

              /* First check if CCM still wants to proceed with reselection */
              if(tdsrrcccm_waiting_for_reselection_cnf() == FALSE)
              {
                TDSRRC_MSG0(MSG_LEGACY_HIGH,"Ignore RESEL_REQ,CCM in IDLE");
                /* No need to send a CNF, nobody is waiting for it */
                rrcllc_next_substate = TDSLLC_IDLE;
              }
              else
              {
                /* Processing of Cell Reselection request succeeded
                 * Send a Cell Reselection Confirm with a Success to the requesting procedure
                 */
                TDSRRC_MSG1(MSG_LEGACY_HIGH,"Sending TDSRRC_CELL_RESELECTION_CNF (Success)to procedure %d",tdsrrcllc_cmd_under_process.procedure);
                (void)tdsrrcllc_send_rrc_cell_reselection_cnf(SUCCESS);
              }
            }
          } /* if(rrcllc_next_substate == TDSLLC_WAIT_NEW_CELL_IND) */
        } /* Successful status in Cell Transition Confirm */
        else  /* Cell Transition Status is Failure */
        {
          /* Process the Setup Cnf failure */
          TDSRRC_MSG0(MSG_LEGACY_ERROR,"Rxed Cell Trans Cnf failure");
          rrcllc_next_substate = TDSLLC_IDLE;
          /* No more lower layer commands are to be sent */
          /* Send a Reselection CNF with Failure back to the procedure */
          TDSRRC_MSG1(MSG_LEGACY_HIGH,"Sending RRC_RESELECTION_CNF Failure to procedure %d",tdsrrcllc_cmd_under_process.procedure);
#ifdef FEATURE_TDSCDMA_UPDATE_SIB7_IN_FACH
          if(tdsrrc_get_state()== TDSRRC_STATE_CELL_FACH)
          {
            rlc_lc_id_type    rlc_dl_log_chl_id;
            int i=0;
            if(tdsrrcllc_cmd_under_process.chan_config.
                    phy_chan_action_list.pccpch_action == TDSLLC_PHYCHAN_SETUP)
            {
              /* BCH setup failed */
              /* Make sure S_PCCPCH status reflects this:
               * Release CCTrCH ID allocated for S_PCCPCH, update status
               * in semi permanent data.
               */
              if(tdsrrcllc_clear_cctrch_id(tdsrrcllc_semi_permanent_data.dl_phy_chan.
                                        pccpch.cctrch_id)
                  == FAILURE)
              {
                TDSRRC_MSG1(MSG_LEGACY_ERROR,"CCTrCH ID %d for S PCCPCH not cleared",tdsrrcllc_semi_permanent_data.dl_phy_chan.pccpch.cctrch_id);
              } /* If could not clear CCTrCH ID */
              tdsrrcllc_semi_permanent_data.dl_phy_chan.pccpch_is_up = FALSE;

              rlc_dl_log_chl_id = tdsrrclcm_check_dl_rlc_lc_id(UE_LOGCHAN_BCCH,
                                                            BCCH_S_RADIO_BEARER_ID,
                                                            UE_MODE_TRANSPARENT);
              
              if (rlc_dl_log_chl_id != TDSRRCLCM_RLC_LC_ID_NOT_FOUND) 
              {
                /* de-allocate LC_ID if only RLC action for BCCH was TDSRLC_ESTABLISH */
                for (i = 0; i < tdsrrcllc_cmd_under_process.chan_config.rlc_config_req_list.dl_tm.nchan; i ++) 
                {
                  if ((tdsrrcllc_cmd_under_process.chan_config.rlc_config_req_list.dl_tm.chan_info[i].lc_id == rlc_dl_log_chl_id)&&
                      (tdsrrcllc_cmd_under_process.chan_config.rlc_config_req_list.dl_tm.chan_info[i].lc_type == UE_LOGCHAN_BCCH) &&
                      (tdsrrcllc_cmd_under_process.chan_config.rlc_config_req_list.dl_tm.dl_tm_act[i].action ==  TDSRLC_ESTABLISH)) 
                  {
                    TDSRRC_MSG0(MSG_LEGACY_HIGH,"Rel Log Chl for BCCH_S");
                    (void)tdsrrclcm_deallocate_dl_rlc_lc_id(rlc_dl_log_chl_id);
                    /* also update config db */
                    if (tdsreselection_config_ptr->rlc_dl_tm_parms.nchan)
                    {
                      tdsreselection_config_ptr->rlc_dl_tm_parms.nchan --;
                    }
                    /* Set number of BCHs in MAC correctly */
                    if(tdsreselection_config_ptr->mac_dl_parms.num_bchs)
                    {
                      tdsreselection_config_ptr->mac_dl_parms.num_bchs --;
                    }                  
                    break;
                  }
                }
              }
            }
          }
#endif

          /* Send a Failure status to the calling procedure */
          (void)tdsrrcllc_send_rrc_cell_reselection_cnf(FAILURE);

          /* Clear Ordered Config if indicated in LLC Command under process */
          if(tdsrrcllc_cmd_under_process.clear_oc_pending)
          {
            TDSRRC_MSG0(MSG_LEGACY_HIGH,"Pending ClearOC on Cell Trans Cnf ");
            tdsrrcllc_clear_ordered_config_now();
            tdsrrcllc_cmd_under_process.clear_oc_pending = FALSE;
          }
        }  /* Cell Transition Status is Failure */
      } /* Reselection Engine is active */
      else
      {
        tdsrrcllc_funneled_cmd_cnf(cmd_ptr, tdsrrcllc_cmd_under_process.procedure, cmd_ptr->cmd_hdr.cmd_id);
        /*Call CSP function to indicate CSP that cel transition CNF is received*/
        tdsrrccsp_cell_trans_cnf_rcvd_at_llc();
        rrcllc_next_substate = TDSLLC_IDLE;
      }
      break;

    case TDSRRC_STOP_LOWER_LAYER_REQ:
    case TDSRRC_RNTI_UPDATE_REQ:
    case TDSRRC_LLC_CMD_REQ:
    case TDSRRC_RESET_L1_REQ:
    case TDSRRC_LOWER_LAYER_DEACT_REQ:
    case TDSRRC_CHANNEL_CONFIG_REQ:
    case TDSRRC_CELL_RESELECTION_REQ:
    case TDSRRC_ABORT_CIPH_CONFIG_REQ:
    case TDSRRC_CIPH_CONFIG_REQ:
      if(( ((uint32)cmd_ptr->cmd_hdr.cmd_id) & TDSCMD_BASE_MASK ) == (uint32)TDSRRC_INT_CMD_BASE)
      {
        (void)tdsrrcllc_put_cmd_on_queue(cmd_ptr);
        TDSRRC_MSG0(MSG_LEGACY_MED,"RRC Internal cmd recvd");
      }
      break;

    default:
      TDSRRC_MSG1(MSG_LEGACY_HIGH,"Unexpected Cmd 0x%x in TDSLLC_WAIT_CPHY_CELL_TRANSITION_CNF",cmd_ptr->cmd_hdr.cmd_id);
      break;
  } /* switch() */

  return(rrcllc_next_substate);

} /* tdsrrcllc_wait_cphy_cell_trans_cnf_handler */


