/*====================================================================
FUNCTION: tdsrrcllc_check_sufficient_act_time()

DESCRIPTION:
  This function checks if there is sufficient activation time to kill
  the pending configuration.

DEPENDENCIES:
  None.

RETURN VALUE:
  TRUE   Sufficient activation time .
  FALSE  Insufficient activation time.

SIDE EFFECTS:
  None.

=====================================================================*/
boolean tdsrrcllc_check_sufficient_act_time(void)
{
  int16   current_frame;
  int16   max_frame_count;
  int16   sdu_to_act_frames, sdu_to_current_frames;
  int16   activate_action_time = 0;

  current_frame   = (int16)tdsseq_get_cfn();
  max_frame_count = MAX_CFN_COUNT;

  /* Grab the activation time from L1. */
  if(FALSE == tdsl1_get_ordered_config_act_time(&activate_action_time))
  {
    TDSRRC_MSG0(MSG_LEGACY_ERROR,"Failed to get act time from L1");
    return FALSE;
  }
                            
  /*Check CFN wrap-around case, where LLC has recieved TDSRRC_CPHY_ACTIVATION_TIME_IND*/
  if(TRUE == tdsrrcllc_recved_act_time_ind)
  {
    TDSRRC_MSG0(MSG_LEGACY_ERROR,"Act time has already passed,Cannot cancel!");
    return FALSE;
  }

                              
  /* Frames from reception of command in RLC to its real activation time, and
   ** to the current frame. */
  sdu_to_act_frames     = activate_action_time - (int16)tdsordered_config_ptr->sdu_time;
  sdu_to_current_frames = current_frame        - (int16)tdsordered_config_ptr->sdu_time;
                             
  /* Results are never really negative.  Normalize to make positive. */
  if (sdu_to_act_frames < 0)
  {
    sdu_to_act_frames += max_frame_count;
  }
               
  if (sdu_to_current_frames < 0)
  {
    sdu_to_current_frames += max_frame_count;
  }
                  
  /* Did processing delay cause us to miss our activation time?  The
  ** sequencer begins processing a pending command 1 frame before its
  ** activation time.  So if we're just 3 frames away, treat it as missed,
  ** and initiate processing now. */
  TDSRRC_MSG2(MSG_LEGACY_HIGH,"Act time:%d Curr Frame:%d",activate_action_time,current_frame);
  TDSRRC_MSG3(MSG_LEGACY_HIGH,"SDUt %d toCurFr %d toActFr %d",
             tdsordered_config_ptr->sdu_time, sdu_to_current_frames, sdu_to_act_frames);
  if ((sdu_to_current_frames + 3) > sdu_to_act_frames)
  {
    /* Rats!  We missed the activation time.  Process command now! */
    TDSRRC_MSG0(MSG_LEGACY_HIGH,"Act time missed cant cancel ");
    return FALSE;
  }
  return TRUE;
}

/*====================================================================
FUNCTION: tdsrrcllc_check_if_chan_config_in_progress_for_sib5_change()

DESCRIPTION:
  This function will return TRUE if channels are being configured for sib5 change (Requested by CSP)
  It will return FALSE other wise

DEPENDENCIES:
  None.

RETURN VALUE:
  TRUE : if channels are being configured for sib change
  FALSE otherwise
SIDE EFFECTS:
  None.

=====================================================================*/
boolean tdsrrcllc_check_if_chan_config_in_progress_for_sib5_change
(
  void
)
{
  boolean status=FALSE;
  if((tdsrrcllc_current_substate != TDSLLC_IDLE &&
     tdsrrcllc_cmd_under_process.valid &&
     tdsrrcllc_cmd_under_process.rrc_current_cmd_id == TDSRRC_CHANNEL_CONFIG_REQ &&
     tdsrrcllc_cmd_under_process.chan_config.chan_config_reason == TDSRRCLLC_CHAN_CFG_REASON_RECONFIG_PCH_FACH &&
     tdsrrcllc_cmd_under_process.procedure == TDSRRC_PROCEDURE_CSP)||
     tdsrrcllc_get_sib5_change_in_progress_flag())
  {
    status = TRUE;
  }
  return status;
}

/*====================================================================
FUNCTION: tdsrrcllc_process_chan_config_request()

DESCRIPTION:
  This function will process the channel config request

DEPENDENCIES:
  None.

RETURN VALUE:
  Next LLC State
  
SIDE EFFECTS:
  None.

=====================================================================*/
tdsrrcllc_substate_e_type tdsrrcllc_process_chan_config_request
(
  tdsrrc_cmd_type *cmd_ptr
)
{
  tdsrrcllc_substate_e_type  rrcllc_next_substate = TDSLLC_IDLE;
  tdsrrc_cmd_type* llc_stored_cmd_ptr;
  tdsrrc_state_e_type rrc_state = tdsrrc_get_state();
  
  TDSRRC_MSG0(MSG_LEGACY_MED,"In Process chan config request");

  if((cmd_ptr->cmd.chan_config_req.procedure == TDSRRC_PROCEDURE_CSP) &&
      (cmd_ptr->cmd.chan_config_req.chan_config_reason ==
            TDSRRCLLC_CHAN_CFG_REASON_RECONFIG_PCH_FACH))
  {
    tdsrrcllc_clear_sib5_change_in_progress_flag();
  }

  /*If DRX req was posted after PCCH Reconfig due to SIB5 change when PCH 
       to FACH or Disconnected to Connecting transition was in progress, trash the 
       DRX request because now the state is either FACH/Connecting.*/
       
  if((cmd_ptr->cmd.chan_config_req.procedure == TDSRRC_PROCEDURE_CSP) &&
     (cmd_ptr->cmd.chan_config_req.chan_config_reason ==
           TDSRRCLLC_CHAN_CFG_REASON_RECONFIG_PCH_FACH)&&
     ((rrc_state == TDSRRC_STATE_CELL_FACH)||
      (rrc_state == TDSRRC_STATE_CONNECTING))
     )
  {
    if( (llc_stored_cmd_ptr = (tdsrrc_cmd_type *)q_check(&tdsrrcllc_cmd_q)) != NULL )
    {
      if((llc_stored_cmd_ptr->cmd_hdr.cmd_id == TDSRRC_LLC_CMD_REQ)
          && (llc_stored_cmd_ptr->cmd.rrc_llc_req.cmd_dest == TDSLAYER1_PHY)
          &&(llc_stored_cmd_ptr->cmd.rrc_llc_req.l1_cmd.cmd_id == TDSL1_CPHY_DRX_REQ))
      {
        tdsrrc_cmd_type *llc_cmd_ptr;
        if((llc_cmd_ptr = (tdsrrc_cmd_type *) q_get(&tdsrrcllc_cmd_q))!= NULL)
        {
          TDSRRC_MSG1(MSG_LEGACY_HIGH,"RRC State is %d. Trash DRX req",rrc_state);
          tdsrrcllc_free_cmd_and_embedded_buf(llc_cmd_ptr);
        }
      }
    }
  }

  {
#ifdef FEATURE_TDSCDMA_RRC_RB_PRIORITY_OPT
    /* Adjust MAC logical channel priority
       SRB 1/2/3/4 - PRIORITY 1/2/3/4
       CS RB - PRIORITY 5
       PS RB - PRIORITY priority + 5
    */
    tdsrrcllc_adjust_oc_mac_logical_channel_priority();
#endif
    tdsrrcllc_update_generic_cmd_process_data(cmd_ptr);
    if(tdsrrcllc_update_cmd_process_data_for_channel_config(cmd_ptr) == SUCCESS)
    {
      /* This function updates the ciphering information for a reconfiguration for
         UM/AM and TM Radio Bearers.  Only if UM/AM bearers are added success is
         returned.  If SUCCESS is returned by SMC then RLC commands are sent to
         update RLC UM and AM ciphering configuration */
      {
        if (SUCCESS == 
            tdsrrcsmc_update_ciphering_config_info_for_reconfig(&tdsrrcllc_cmd_under_process.chan_config.rlc_config_req_list,
                                                             tdsrrcllc_cmd_under_process.procedure))
        {
          tdsrrcllc_rlc_cipher_update_needed = TRUE;
        }
      }
      if(tdsrrcllc_command_engine(tdsrrcllc_current_substate, &rrcllc_next_substate)
         == FAILURE)
      {
        ERR_FATAL("RRC Config request processing failure",0,0,0);
      }
      
      if(rrcllc_next_substate == TDSLLC_IDLE)
      {
        /* This implies no more lower layer commands are to be sent - Can this happen
         * in TDSLLC_IDLE ?
         */
        /* Send a RRC Config CNF back to the procedure and change RRC state */
        if((tdsrrcllc_cmd_under_process.valid) &&
           (tdsrrcllc_cmd_under_process.rrc_current_cmd_id == TDSRRC_CHANNEL_CONFIG_REQ))
        {
          rrcllc_next_substate = tdsrrcllc_handle_completion_of_chan_config_req();
        } /* if(tdsrrcllc_cmd_under_process.valid)... */
      } /* if(rrcllc_next_substate == TDSLLC_IDLE) */
    } /* If Channel Config Command data updated successfully */
    else
    {
      /* Updating of Channel Config Command data failed */
      /* Send a Channel Config Confirm with a failure to the requesting procedure */
      /*Discard the OC only if it was set by the procedure that has sent current channel config request */
      if(( tdsrrcllc_get_ordered_config_status() != TDSOC_NOT_SET) && (tdsordered_config.set_by_proc == tdsrrcllc_cmd_under_process.procedure ))
      {
        TDSRRC_MSG0(MSG_LEGACY_HIGH,"Discard Oc and set config_ptr_in_use to CURRENT_CONFIG  ");
        tdsrrcllc_discard_oc();
      }
            
  
      TDSRRC_MSG1(MSG_LEGACY_MED,"Sending TDSRRC_CHANNEL_CONFIG_CNF (Failure)to procedure %d",tdsrrcllc_cmd_under_process.procedure);
      if(tdsrrcllc_cmd_under_process.chan_config.cnf_needed)
      {
        (void)tdsrrcllc_send_rrc_channel_config_cnf(tdsrrcllc_cmd_under_process.procedure,
                                                 tdsrrcllc_cmd_under_process.chan_config_transaction_id,
                                                 TDSRRCLLC_CHAN_CFG_FAILURE_OTHER);
      }
    }
  }
  return rrcllc_next_substate;
}

/*===========================================================================

FUNCTION: tdsrrcllc_get_log_chan_action_for_rb_action

DESCRIPTION:
  This  function returns the RLC action based on RB Action

DEPENDENCIES:
  None.

RETURN VALUE:
  RLC Action

SIDE EFFECTS:
  None
===========================================================================*/
tdsrlc_channel_action_e_type  tdsrrcllc_get_log_chan_action_for_rb_action
(
  tdsrrc_rb_config_type *rb_config
    , uint16 *ul_cfg_mask,
     uint16 * dl_cfg_mask

)
{
  tdsrlc_channel_action_e_type  log_chan_action =TDSRLC_MODIFY ;


  switch(rb_config->rb_config)
  {
    case TDSESTABLISH_RB:
     log_chan_action = TDSRLC_ESTABLISH;
     TDSRRC_MSG0(MSG_LEGACY_MED,"RLC Action: Establish");
     break;
    case TDSRELEASE_RB:
     log_chan_action = TDSRLC_RELEASE;
     TDSRRC_MSG0(MSG_LEGACY_MED,"RLC Action: Release");
     break;
    case TDSRECONFIG_RB:
     log_chan_action = TDSRLC_MODIFY;
     *ul_cfg_mask = TDSRLC_MODIFY_CFG;;
     *dl_cfg_mask = TDSRLC_MODIFY_CFG;;
    TDSRRC_MSG2(MSG_LEGACY_HIGH,"RLC MULTIPLE: UL Mask is %x and DL Mask is %x",ul_cfg_mask,dl_cfg_mask);

     TDSRRC_MSG0(MSG_LEGACY_MED,"RLC Action: Modify");
      break;
    case  TDSRECONFIG_RB_OTA:

          log_chan_action  = TDSRLC_MODIFY;
          *ul_cfg_mask = rb_config->ul_cfg_mask;
          *dl_cfg_mask = rb_config->dl_cfg_mask;
          TDSRRC_MSG2(MSG_LEGACY_HIGH,"RLC MULTIPLE: UL Mask is %x and DL Mask is %x",ul_cfg_mask,dl_cfg_mask);
     break;
    default:
      TDSRRC_MSG1(MSG_LEGACY_ERROR,"In valid rb_config %d",rb_config);
  }
  return log_chan_action;
}

/*===========================================================================

FUNCTION: tdsrrcllc_curr_cmd_rel_all_req

DESCRIPTION:
  This  function returns if the current cmd is CRLC REL all req. 
  In that state L2 ack can be ignored.

DEPENDENCIES:
  None.

RETURN VALUE:
TRUE/FALSE

SIDE EFFECTS:
  None
===========================================================================*/
boolean tdsrrcllc_curr_cmd_rel_all_req
(
  void
)
{
  if(((tdsrrcllc_cmd_under_process.chan_config.current_cmd_engine == TDSLLC_RELEASE_ALL_CHAN_ENGINE)
     ||(tdsrrcllc_cmd_under_process.chan_config.current_cmd_engine == LLC_STOP_TDS_MODE_ENGINE)
     ||(tdsrrcllc_cmd_under_process.chan_config.current_cmd_engine == TDSLLC_DEACT_ENGINE))
     && (tdsrrcllc_current_substate != TDSLLC_IDLE))
  {
    TDSRRC_MSG1(MSG_LEGACY_HIGH," Current engine %d",tdsrrcllc_cmd_under_process.chan_config.current_cmd_engine);
    return TRUE;
  }
  return FALSE;
}

