#ifdef FEATURE_TDSCDMA_HSUPA
/*====================================================================
FUNCTION: tdsrrcllc_check_if_config_mismatch_for_non_schedule()

DESCRIPTION:
  This function will check only non-schedule is start, OTA only reconfig 
  schedule elements, RRC will not notify the elements to L1.

DEPENDENCIES:
  None.

RETURN VALUE:
  TRUE : RRC not notify L1 reconfig HSUPA
  FALSE  RRC notify L1 reconfig HSUPA.
  
SIDE EFFECTS:
  None.

=====================================================================*/
boolean tdsrrcllc_check_if_config_mismatch_for_non_schedule
(
  void
)
{
  boolean status = FALSE;

  if ((tdsordered_config_ptr->l1_e_req_mask & TDSRRCLLC_EUL_START) || 
        (tdsordered_config_ptr->l1_e_req_mask & TDSRRCLLC_EUL_STOP))
  {
    /* RRC will notify L1 start/stop HSUPA */
    return status;
  }
  
  /* Current OTA reconfig UL, DL or Non-schedule  */
  if(tdsordered_config_ptr->l1_e_req_mask & TDSRRCLLC_EUL_RECFG_UL) 
  {
    if (tdsordered_config_ptr->l1_e_info.e_ul_info.e_ul_info_mask & TDSL1_ERUCCH_INFO_INCL)
    {
      /* Current OTA reconfig ERUCCH, but schedule transmission not start this time, 
              RRC will not notify L1 ERUCCH info */
      if (!(tdsordered_config_ptr->hsupa_start_mask & TDSRRC_SCHED_START))
      {
        /* RRC not notify L1 ERUCCH info through clear mask */
        TDSRRC_MSG0(MSG_LEGACY_HIGH,"RRCEUL: clear ERUCCH flg in e_ul_info_mask");
        tdsordered_config_ptr->l1_e_info.e_ul_info.e_ul_info_mask &= ~TDSL1_ERUCCH_INFO_INCL;

        if (tdsordered_config_ptr->l1_e_info.e_ul_info.e_ul_info_mask == 0)
        {
          /* Current OTA not reconfig HARQ or EPUCH for non-schedule, RRC will not notify L1 update UL info */
          TDSRRC_MSG0(MSG_LEGACY_HIGH,"RRCEUL: UL reconfig isn't applicable to only non-schedule running ");
          tdsordered_config_ptr->l1_e_req_mask &= ~TDSRRCLLC_EUL_RECFG_UL;
        }
      }
    }
  }
  
  if(tdsordered_config_ptr->l1_e_req_mask & TDSRRCLLC_EUL_RECFG_DL) 
  {
    /* Current OTA reconfig E_AGCH or E_HICH, but schedule transmission not start this time, 
              RRC will not notify L1 E_AGCH or E_HICH info */
    if ((tdsordered_config_ptr->l1_e_info.e_dl_info.e_dl_channel_mask & TDSL1_E_AGCH_INFO_INCL) ||
        (tdsordered_config_ptr->l1_e_info.e_dl_info.e_dl_channel_mask & TDSL1_E_HICH_INFO_INCL))  
       
    {
      if (!(tdsordered_config_ptr->hsupa_start_mask & TDSRRC_SCHED_START))
      {
        /* RRC not notify L1 EHICH or EAGCH info through clear mask */
        TDSRRC_MSG0(MSG_LEGACY_HIGH,"RRCEUL : clear E-HICH or E-AGCH flg in e_dl_channel_mask");
        tdsordered_config_ptr->l1_e_info.e_dl_info.e_dl_channel_mask &= 
                          ~(TDSL1_E_HICH_INFO_INCL | TDSL1_E_AGCH_INFO_INCL);
        /* Current OTA not reconfig ERNTI for non-schedule, RRC will not notify L1 update DL info */
        if (tdsordered_config_ptr->l1_e_info.e_dl_info.e_dl_channel_mask == 0)
        {
          TDSRRC_MSG0(MSG_LEGACY_HIGH,"RRCEUL: DL reconfig isn't applicable to only non-schedule running ");
          tdsordered_config_ptr->l1_e_req_mask &= ~TDSRRCLLC_EUL_RECFG_DL;
        }          
      }
    }
  }
  /* If current OTA not reconfig Non-schedule grant,UL or DL, RRC will not notify L1 update HSUPA configuration. */
  if (tdsordered_config_ptr->l1_e_req_mask == 0)
  {
    TDSRRC_MSG1(MSG_LEGACY_HIGH,"RRCEUL: clear l1_e_req_mask is %x ",tdsordered_config_ptr->l1_e_req_mask);
    status = TRUE;
  }
  return status;
}
#endif


