/*===========================================================================
FUNCTION   tdsrrcllc_cmac_ul_remove_invalid_tfc

DESCRIPTION
  This function checks the TFCS table to check if for any TFCI, the number
  of transport blocks exceeds the current limitation of L1 which is 16 blks.
  In case the numebr of transport blocks exceeds the l1 limitation of
  16 blks or 5120 bits then, RRC sets that TFCI to invalid, so that MAC would
  never choose that TFCI.
  And RRC remove the invalid TFC,which TFCI length exceed the TFCI coding

DEPENDENCIES
  None.

RETURN VALUE


SIDE EFFECTS
  None.
===========================================================================*/
void tdsrrcllc_cmac_ul_remove_invalid_tfc(tdsmac_ul_tfcs_type *tfcs_ptr, uint8 tfci_coding,boolean *flag_tfc_remove)
{
  uint16 i = 0;


   /* if the tfci coding is bit4, the TFCI should be 0,1, and MAC will transfer the 0 or 1 to L1.
       but L1 will add 1 at burst, so we use 1 here set the TFC is not allowed.
       Same as others.*/
	if(TDSL1_TFCI_CODING_BITS_4 == tfci_coding
		  && tfcs_ptr->ntfc >= 2)
	{
    *flag_tfc_remove = TRUE;
    for (i = 1;i<tfcs_ptr->ntfc;i++ )
    {
      tfcs_ptr->tfc_info[i].control_flag = TDSTFC_NOT_ALLOWED;
    }
    TDSRRC_MSG2(MSG_LEGACY_ERROR,"Error - UL DPCH TFCI coding bits = %d not match with ntfc=%d",tfci_coding,tfcs_ptr->ntfc);
                
	}
	else if(TDSL1_TFCI_CODING_BITS_8 == tfci_coding
					 && tfcs_ptr->ntfc >= 4)
	{
    *flag_tfc_remove = TRUE;
    for (i=3;i<tfcs_ptr->ntfc;i++ )
    {
      tfcs_ptr->tfc_info[i].control_flag = TDSTFC_NOT_ALLOWED;
    }
    TDSRRC_MSG2(MSG_LEGACY_ERROR,"Error - UL DPCH TFCI coding bits = %d not match with ntfc=%d",tfci_coding,tfcs_ptr->ntfc);
          
	}
	else if(TDSL1_TFCI_CODING_BITS_16 == tfci_coding
					 && tfcs_ptr->ntfc >= 32)
	{
    *flag_tfc_remove = TRUE;
    for (i = 31;i<tfcs_ptr->ntfc;i++ )
    {
      tfcs_ptr->tfc_info[i].control_flag = TDSTFC_NOT_ALLOWED;
    }
    TDSRRC_MSG2(MSG_LEGACY_ERROR,"Error - UL DPCH TFCI coding bits = %d not match with ntfc=%d",tfci_coding,tfcs_ptr->ntfc);

	}
	else if(TDSL1_TFCI_CODING_BITS_32 == tfci_coding
					 && tfcs_ptr->ntfc >= TDSUE_MAX_TFC)
	{
    *flag_tfc_remove = TRUE;
    for (i = TDSUE_MAX_TFC - 1;i<tfcs_ptr->ntfc;i++)
    {
      tfcs_ptr->tfc_info[i].control_flag = TDSTFC_NOT_ALLOWED;
    }
    TDSRRC_MSG2(MSG_LEGACY_ERROR,"Error - UL DPCH TFCI coding bits = %d not match with ntfc=%d",tfci_coding,tfcs_ptr->ntfc);
					
	}
	else if (TDSL1_TFCI_CODING_BITS_0 == tfci_coding)
	{
    TDSRRC_MSG2(MSG_LEGACY_ERROR,"Error - UL DPCH TFCI coding bits = %d not match with ntfc=%d",tfci_coding,tfcs_ptr->ntfc);
		
	}
  return;
}


