#ifdef FEATURE_TDSCDMA_ONE_SIDE_REEST
/*====================================================================
FUNCTION: tdsrrcllc_check_and_stop_rlc_entity_due_to_reest()

DESCRIPTION:
  This function is used to stop the RLC entity.

DEPENDENCIES:
  None.

RETURN VALUE:

  
SIDE EFFECTS:
  None.

=====================================================================*/
void tdsrrcllc_check_and_stop_rlc_entity_due_to_reest(tdsrlc_am_config_req_type * am_rb_config)
{
  uint8 i = 0;

  tdsrlc_dl_stop_request_type stop_dl_rlc_req = {0};

  tdsrlc_ul_stop_suspend_request_type stop_ul_rlc_req = {0};

  tdsrlc_ul_stop_suspend_cnf_type ul_crlc_suspend_stop_cnf ={0};
  uint8 rb_num = 0;
  rlc_lc_id_type dl_lc_id = TDSRRCLCM_RLC_LC_ID_NOT_FOUND;
  rlc_lc_id_type ul_lc_id = TDSRRCLCM_RLC_LC_ID_NOT_FOUND;
  

  memset(&tdsrrcrlc_continue_reest, 0, sizeof(tdsrrcllc_continue_rlc_data_type) );
  for (i = 0;(i < am_rb_config->nentity) && (i < TDSUE_MAX_AM_ENTITY);i++)
  {
    if (((am_rb_config->am_act[i].dl_cfg_mask&TDSRLC_RE_ESTABLISH_CFG) == TDSRLC_RE_ESTABLISH_CFG)&&
      ((am_rb_config->am_act[i].ul_cfg_mask&TDSRLC_RE_ESTABLISH_CFG) != TDSRLC_RE_ESTABLISH_CFG))
    {
      tdsrrcrlc_continue_reest.rb_id[rb_num] = am_rb_config->am_info[i]->common_config.rb_id;
      TDSRRC_MSG1(MSG_LEGACY_HIGH,"RRC_ONE_SIDE: DL:STOP RB ID is %d ",tdsrrcrlc_continue_reest.rb_id[rb_num]);
      rb_num++;

    }
    else if (((am_rb_config->am_act[i].ul_cfg_mask&TDSRLC_RE_ESTABLISH_CFG) == TDSRLC_RE_ESTABLISH_CFG)&&
      ((am_rb_config->am_act[i].dl_cfg_mask&TDSRLC_RE_ESTABLISH_CFG) != TDSRLC_RE_ESTABLISH_CFG))
    {
      tdsrrcrlc_continue_reest.rb_id[rb_num] = am_rb_config->am_info[i]->common_config.rb_id;
      TDSRRC_MSG1(MSG_LEGACY_HIGH,"RRC_ONE_SIDE: UL:STOP RB ID is %d ",tdsrrcrlc_continue_reest.rb_id[rb_num]);
      rb_num++;

    }
    else if (((am_rb_config->am_act[i].ul_cfg_mask&TDSRLC_RE_ESTABLISH_CFG) == TDSRLC_RE_ESTABLISH_CFG)&&
      ((am_rb_config->am_act[i].dl_cfg_mask&TDSRLC_RE_ESTABLISH_CFG) == TDSRLC_RE_ESTABLISH_CFG))
    {
      tdsrrcrlc_continue_reest.rb_id[rb_num] = am_rb_config->am_info[i]->common_config.rb_id;
      TDSRRC_MSG1(MSG_LEGACY_HIGH,"RRC_ONE_SIDE: UL and DL:STOP RB ID is %d ",tdsrrcrlc_continue_reest.rb_id[rb_num]);
      rb_num++;
    }
  }
  
  tdsrrcrlc_continue_reest.rb_num = rb_num;
  if (tdsrrcrlc_continue_reest.rb_num > 0)
  {
    for(i = 0;i < tdsrrcrlc_continue_reest.rb_num; i++)
    {
      dl_lc_id = tdsrrclcm_get_dl_rlc_lc_id(tdsrrcrlc_continue_reest.rb_id[i]);
      if (dl_lc_id == TDSRRCLCM_RLC_LC_ID_NOT_FOUND)
      {
        TDSRRC_MSG1(MSG_LEGACY_ERROR,"RRC_ONE_SIDE:Invalid DL LC ID for RB %d",tdsrrcrlc_continue_reest.rb_id[i]);
        memset(&tdsrrcrlc_continue_reest, 0, sizeof(tdsrrcllc_continue_rlc_data_type) );
        return ;
      }
      ul_lc_id = tdsrrclcm_get_ul_rlc_lc_id(tdsrrcrlc_continue_reest.rb_id[i]);
      if (ul_lc_id == TDSRRCLCM_RLC_LC_ID_NOT_FOUND)
      {
        TDSRRC_MSG1(MSG_LEGACY_ERROR,"RRC_ONE_SIDE:Invalid UL LC ID for RB %d",tdsrrcrlc_continue_reest.rb_id[i]);
        memset(&tdsrrcrlc_continue_reest, 0, sizeof(tdsrrcllc_continue_rlc_data_type) );
        return ;
      }
      stop_dl_rlc_req.lc_id[i] = dl_lc_id;
      stop_ul_rlc_req.suspend_stop[i].lc_id = ul_lc_id;
    }
  }
  stop_dl_rlc_req.nchan = tdsrrcrlc_continue_reest.rb_num;
  stop_ul_rlc_req.nchan = tdsrrcrlc_continue_reest.rb_num;
  stop_ul_rlc_req.ul_cmd_type = TDSRLC_STOP_CMD;
  TDSRRC_MSG0(MSG_LEGACY_HIGH,"RRC_ONE_SIDE: STOP Two side");


  tdscrlc_dl_perform_stop_functionality(&stop_dl_rlc_req);    
  tdscrlc_ul_perform_suspend_or_stop_functionality(&stop_ul_rlc_req,&ul_crlc_suspend_stop_cnf);


  
  
}
#endif
#ifdef FEATURE_TDSCDMA_TVM_BLOCK
/*===========================================================================

FUNCTION  tdsrrc_calculate_block_tvm_time

DESCRIPTION
  This function is used to calculate the tvm block time after HO

DEPENDENCIES


RETURN VALUE
  TMV block time interval

SIDE EFFECTS
  None
===========================================================================*/
uint16 tdsrrc_calculate_block_tvm_time(void)
{
  uint16 current_cfn = 0; 
  uint16 act_offset = 0;
  uint16 tdsrrc_block_tvm_time_interval = 0;

  /*Activatin Offset < Td, then the activation time already passed*/
  if (tdsordered_config_ptr->act_time_type == TDSL1_ACTIVATION_TIME_CFN)
  {
    current_cfn = tdsseq_get_cfn();
    act_offset = (256 + tdsordered_config_ptr->activation_time - current_cfn) & 0xFF;
    TDSRRC_MSG3(MSG_LEGACY_HIGH,"current cfn:%d, activation time:%d, act_offset: %d", 
                current_cfn, 
                tdsordered_config_ptr->activation_time, 
                act_offset);

    tdsrrc_block_tvm_time_interval = act_offset*10 + TDSRRC_BLOCK_TVM_EXTRA_TIME;
  }
  else
  {
    tdsrrc_block_tvm_time_interval = TDSRRC_BLOCK_TVM_EXTRA_TIME;
  }

  return tdsrrc_block_tvm_time_interval;
}
#endif/*#ifdef FEATURE_TDSCDMA_TVM_BLOCK*/

